toolCall.argumentsJson:
{"CommandLine":"$exePath = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto\PROGRAMA_PERFECTO_XVIEW_B866V2.exe"
$workDir = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto"
$logFile = "c:\Users\andre\OneDrive\Desktop\xview\programa perfecto\BITACORA_EN_VIVO_EXE.log"

$psi = New-Object System.Diagnostics.ProcessStartInfo
$psi.FileName = $exePath
$psi.WorkingDirectory = $workDir
$psi.UseShellExecute = $true
$psi.WindowStyle = [System.Diagnostics.ProcessWindowStyle]::Normal
$p = [System.Diagnostics.Process]::Start($psi)

Start-Sleep -Seconds 1
Write-Host "[VENTANA ABIERTA v4.1] PID=$($p.Id)"

$lastLen = 0
if (Test-Path $logFile) { $lastLen = (Get-Item $logFile).Length }
$seenPids = @{}

while ($true) {
    if (Test-Path $logFile) {
        $item = Get-Item $logFile
        if ($item.Length -gt $lastLen) {
            $fs = [System.IO.File]::Open($logFile, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::ReadWrite)
            $fs.Seek($lastLen, [System.IO.SeekOrigin]::Begin) | Out-Null
            $sr = New-Object System.IO.StreamReader($fs, [System.Text.Encoding]::UTF8)
            $newText = $sr.ReadToEnd()
            $sr.Close()
            $fs.Close()
            $lastLen = $item.Length
            if ($newText) { Write-Host -NoNewline $newText }
        }
    }
    Get-CimInstance Win32_Process -Filter "Name='cmd.exe' OR Name='fastboot.exe'" -ErrorAction SilentlyContinue | ForEach-Object {
        if (-not $seenPids.ContainsKey($_.ProcessId)) {
            $seenPids[$_.ProcessId] = $true
            if ($_.CommandLine -match "Evoca|B866V2|fastboot") {
                Write-Host "[RASTREADOR EVOCA/FASTBOOT PID=$($_.ProcessId)] $($_.CommandLine)"
            }
        }
    }
    Start-Sleep -Milliseconds 350
}","IsDaemon":true,"WaitMsBeforeAsync":2500,"toolSummary":"Launch v4.1 window and monitor Programa Perfecto + Evoca in real time"}
